import { useEffect, useState } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

function CandidatesPage({ auth }) {
  const [groupedCandidates, setGroupedCandidates] = useState({});

  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/candidates/grouped`, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setGroupedCandidates(res.data);
      } catch (err) {
        console.error("Failed to fetch candidates", err);
      }
    };
    fetchCandidates();
  }, [auth.token]);

  return (
    <div style={{ padding: 20 }}>
      <h1>Candidates</h1>
      {Object.keys(groupedCandidates).map((position) => (
        <div key={position} style={{ marginBottom: 30 }}>
          <h2>{position}</h2>
          <ul>
            {groupedCandidates[position].map((c) => (
              <li key={c._id} style={{ marginBottom: 10 }}>
                <strong>{c.firstName} {c.lastName}</strong> - {c.partylist}
              </li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  );
}

export default CandidatesPage;
